#!/usr/bin/env node
/**
 * Tests for the input filters and the write-grant gate of scripts/db-ro.ps1. Zero dependencies —
 * `node:test` on Node 18+, plus pwsh 7.
 *
 *   node --test "tools/*.test.mjs"
 *
 * The script runs a whole query on load, so a function is lifted out of it by its PowerShell AST and
 * run in isolation, with `Stop-Wrapper` stubbed to throw "[code] message". Nothing ever reaches a
 * database.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPT = join(dirname(fileURLToPath(import.meta.url)), '..', 'scripts', 'db-ro.ps1');
const hasPwsh = spawnSync('pwsh', ['-NoProfile', '-Command', '$PSVersionTable.PSVersion.Major'], { encoding: 'utf8' }).status === 0;
const skip = hasPwsh ? false : 'pwsh 7 not on PATH';

/**
 * Calls function `fn` of db-ro.ps1 once per entry of `calls` (each an array of arguments), after the
 * PowerShell `prelude`. Returns `{ ok, value }` or `{ ok: false, error }` for each call.
 */
function call(fn, calls, prelude = '') {
  const driver = `
    ${prelude}
    $Fn = $env:DBRO_FN
    $ast = [System.Management.Automation.Language.Parser]::ParseFile($env:DBRO_SCRIPT, [ref]$null, [ref]$null)
    $def = $ast.Find({ param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq $Fn }, $true)
    function Stop-Wrapper([string]$Message, [int]$Code = 2) { throw "[$Code] $Message" }
    . ([scriptblock]::Create($def.Extent.Text))
    $out = foreach ($c in ($env:DBRO_JSON | ConvertFrom-Json)) {
      $arguments = @($c.a)
      try { @{ ok = $true; value = (& $Fn @arguments) } } catch { @{ ok = $false; error = [string]$_.Exception.Message } }
    }
    ConvertTo-Json -InputObject @($out) -Compress -Depth 5`;
  const r = spawnSync('pwsh', ['-NoProfile', '-Command', driver], {
    encoding: 'utf8',
    env: { ...process.env, DBRO_SCRIPT: SCRIPT, DBRO_FN: fn, DBRO_JSON: JSON.stringify(calls.map((a) => ({ a }))) },
  });
  assert.equal(r.status, 0, r.stderr);
  return JSON.parse(r.stdout);
}

const verdicts = (fn, texts, prelude) => call(fn, texts.map((t) => [t]), prelude);

test('Assert-PlainPgSql rejects what turns the read-only session off: SET ROLE, RESET, DISCARD', { skip }, () => {
  const rejected = [
    'SET default_transaction_read_only = off',
    'SELECT set_config(\'default_transaction_read_only\', \'off\', false)',
    'SET ROLE postgres',
    'RESET ALL',
    'reset default_transaction_read_only',
    'DISCARD ALL',
    'select 1; discard all',
    'select 1; RESET ALL;',
  ];
  verdicts('Assert-PlainPgSql', rejected).forEach((r, i) => {
    assert.equal(r.ok, false, rejected[i]);
    assert.match(r.error, /Input rejected/, rejected[i]);
  });
});

test('Assert-PlainPgSql keeps plain reads', { skip }, () => {
  const plain = [
    'SELECT 1',
    'select id, name from users where id = 7',
    'WITH t AS (SELECT 1) SELECT * FROM t',
    'SELECT * FROM reset_tokens',            // a name that merely starts with the word
    'SELECT * FROM discarded_orders',
    '\\dt',
  ];
  verdicts('Assert-PlainPgSql', plain).forEach((r, i) => assert.equal(r.ok, true, plain[i]));
});

test('Confirm-WriteGrants: without the flag it stops with exit 4 and lists every grant; with it, it warns', { skip }, () => {
  const grants = ['permission SERVER: ALTER ANY LOGIN', 'role membership db_datawriter'];
  const [refused] = call('Confirm-WriteGrants', [['This login on database \'Sales\'', grants]], '$AcceptWriteGrant = $false; $script:WriteGrantsAccepted = $false');
  assert.equal(refused.ok, false);
  assert.match(refused.error, /^\[4\]/);
  assert.match(refused.error, /ALTER ANY LOGIN/);
  assert.match(refused.error, /db_datawriter/);
  assert.match(refused.error, /ask once/);

  const [accepted] = call('Confirm-WriteGrants', [['This login on database \'Sales\'', grants]], '$AcceptWriteGrant = $true; $script:WriteGrantsAccepted = $false');
  assert.equal(accepted.ok, true);
  assert.match(accepted.value, /write grants accepted, client-side filter only/);
  assert.match(accepted.value, /ALTER ANY LOGIN/);
});

test('Assert-ReadStatements (write grants accepted): only plain SELECT / WITH statements pass', { skip }, () => {
  const plain = [
    'SELECT 1',
    'select top 50 * from dbo.Orders where Id = 7;',
    'WITH t AS (SELECT 1 AS x) SELECT * FROM t',
    "select 'drop table x' as note",                       // a literal is data
    '-- delete everything\nSELECT updated_at FROM t',      // a comment, and a column that merely starts with a keyword
    'SELECT 1\nGO\nSELECT 2',
  ];
  verdicts('Assert-ReadStatements', plain.map((t) => t), '').forEach((r, i) => assert.equal(r.ok, true, `${plain[i]} -> ${r.error}`));

  const refused = [
    'UPDATE dbo.Orders SET Total = 0',
    'select 1; delete from dbo.Orders',
    'WITH x AS (SELECT 1) DELETE FROM t',
    'SELECT * INTO #copy FROM dbo.Orders',
    'SELECT 1\nGO\nDROP TABLE dbo.Orders',
    'EXEC sp_who',
    'SELECT * FROM t FOR UPDATE',
    '/* select */ DROP TABLE t',
    'SELECT * FROM OPENROWSET(\'SQLNCLI\', \'x\', \'select 1\')',
    'select pg_read_file(\'/etc/passwd\')',
  ];
  call('Assert-ReadStatements', refused.map((t) => [t, 'sqlserver'])).forEach((r, i) => {
    assert.equal(r.ok, false, refused[i]);
    assert.match(r.error, /write grants were accepted/, refused[i]);
  });
});
